// Alegra no documenta la forma exacta de lo que manda el webhook, así que aquí
// no confiamos en ella: buscamos el id del cliente donde pueda estar y con eso
// le volvemos a preguntar a Alegra la ficha completa.

const crudo = (items[0] && items[0].json) || {};
const cuerpo = crudo.body !== undefined ? crudo.body : crudo;
const base = Array.isArray(cuerpo) ? cuerpo[0] || {} : cuerpo;

const posibles = [
  base.id,
  base.contactId,
  base.clientId,
  base.idContact,
  base.data && base.data.id,
  base.contact && base.contact.id,
  base.client && base.client.id,
  base.resource && base.resource.id,
  base.payload && base.payload.id,
];

const clienteId = posibles
  .map((v) => (v === undefined || v === null ? '' : String(v).trim()))
  .find((v) => v !== '');

if (!clienteId) {
  throw new Error(
    'No encontré el id del cliente en lo que mandó Alegra. Esto fue lo que llegó: ' +
      JSON.stringify(cuerpo).slice(0, 500)
  );
}

return [{ json: { clienteId } }];

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const CUPO_POR_DEFECTO = 2000000;   // el cupo de crédito que le pones a los nuevos
const MONEDA = 'COP';
const TU_EMPRESA = 'nuestra empresa';   // cómo quieres que te nombre el correo
// ──────────────────────────────────────────────────────────────────────

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const c = (items[0] && items[0].json) || {};

const texto = (v) => (v === undefined || v === null ? '' : String(v).trim());

const nombre = texto(c.name) || 'Cliente sin nombre';
const identificacion =
  texto(c.identificationObject && c.identificationObject.number) ||
  texto(c.identification);
const correo = texto(c.email);
const telefono = texto(c.phonePrimary) || texto(c.mobile);

const dir = c.address || {};
const ciudad = texto(dir.city);
const direccion = texto(dir.address);

const cupoActual = Number(c.creditLimit ?? 0);
const necesitaCupo = !(cupoActual > 0);

// ── Qué le falta a la ficha ──
const faltantes = [];
if (!identificacion) faltantes.push('Identificación');
if (!correo) faltantes.push('Correo');
if (!telefono) faltantes.push('Teléfono');
if (!direccion) faltantes.push('Dirección');
if (necesitaCupo) faltantes.push('Cupo de crédito');

const estadoFicha =
  faltantes.length === 0
    ? 'Completo'
    : faltantes.length <= 2
      ? 'Le falta poco'
      : 'Incompleto';

// ── La fecha en que quedó creado ──
const creado = texto(c.created_at) || texto(c.createdAt);
const fechaCreacion = creado
  ? creado.slice(0, 10)
  : (() => {
      const h = new Date();
      return (
        h.getFullYear() +
        '-' + String(h.getMonth() + 1).padStart(2, '0') +
        '-' + String(h.getDate()).padStart(2, '0')
      );
    })();

// ── El correo de bienvenida ──
// A una persona la saludamos por el nombre de pila. A una empresa, por su nombre
// completo: 'Hola, Ferretería' sonaría raro.
const esPersona = texto(c.kindOfPerson) === 'PERSON_ENTITY';
const nombreDePila = texto(c.nameObject && c.nameObject.firstName);
const saludo = esPersona && nombreDePila ? nombreDePila : nombre;

const mensaje = [
  '<p>Hola, ' + saludo + '.</p>',
  '<p>Ya quedaste registrado como cliente de ' + TU_EMPRESA + '. ' +
    'Desde ahora te vamos a facturar a nombre de <b>' + nombre + '</b>' +
    (identificacion ? ' con la identificación <b>' + identificacion + '</b>' : '') +
    '.</p>',
  correo
    ? '<p>Las facturas te van a llegar a <b>' + correo + '</b>. ' +
      'Si prefieres otro correo, respóndenos y lo cambiamos.</p>'
    : '',
  '<p>Cualquier cosa que necesites, este correo es el canal.</p>',
  '<p>Gracias por la confianza.</p>',
].filter(Boolean).join('\n');

return [
  {
    json: {
      clienteId: String(c.id ?? ''),
      nombre,
      identificacion: identificacion || 'Sin identificación',
      correo,
      tieneCorreo: correo !== '',
      telefono: telefono || 'Sin teléfono',
      ciudad: ciudad || 'Sin ciudad',
      estadoFicha,
      faltantesTexto: faltantes.length ? faltantes.join(', ') : 'Nada, está completo',
      fechaCreacion,
      cupoActual,
      necesitaCupo,
      cupoSugerido: CUPO_POR_DEFECTO,
      cupoParaNotion: necesitaCupo ? CUPO_POR_DEFECTO : cupoActual,
      cupoTexto: plata(necesitaCupo ? CUPO_POR_DEFECTO : cupoActual),
      asunto: 'Bienvenido, ' + saludo,
      mensaje,
    },
  },
];
